def material_markup(key):
    m = MATERIALS[key]
    h = lambda t: f"[b][color=a66a00]{t}[/color][/b]"
    steps = "\n".join(f"  {i}. {s}" for i, s in enumerate(m["steps"], 1))
    return (f"[b]{m['title']}[/b]\n\n{h('What to look for')}\n{m['look_for']}\n\n{h('How to draw it')}\n{steps}\n\n"
            f"{h('Pencils')}\n{m['pencils']}\n\n{h('Common mistakes')}\n{m['mistakes']}")
